package com.eduflow.app.data

import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class BackupFormatTest {
    private val data = BackupData(listOf(SubjectDto(1,"Математика","Мат","Учител","101",0xFF1565C0)), listOf(TemplateDto(2,"Седмица А")), CycleConfigDto(1,"2026-09-07",2), listOf(CycleEntryDto(3,0,2)), listOf(SlotDto(4,2,1,1,"08:00","08:45",1,null,null,null)), listOf(PrivateDto(id=5,subjectId=1,weekday=7,start="16:00",end="17:00",startDate="2026-09-13",endDate=null,interval=1,teacher=null,room=null,enabled=true,privateName="Подготовка за матура",privateLocationKind="ONLINE")), listOf(LessonDto(6,"2026-09-14","08:00","08:45",1,4,null,"SCHOOL","ACTIVE",null,null,"Какво правихме",null),LessonDto(7,"2026-09-20","16:00","17:00",1,null,5,"PRIVATE","ACTIVE",null,null,null,"Бележки")), emptyList(), emptyList(), listOf(TaskDto(8,"Домашна работа",null,1,6,7,"HOMEWORK","MUST","PENDING","2026-09-20T16:00",null,"2026-09-14T09:00")), listOf(ChecklistDto(9,8,"Стъпка",false,0)), listOf(ReminderDto(10,8,"ONE_DAY_BEFORE",null,true,"2026-09-14T09:00")))
    @Test fun versionedBackupRoundTripPreservesIdsRelationshipsAndCyrillic() { val original=PortableBackup(BackupManifest(createdAt="2026-09-11T10:00"),data,BackupSettings(true,true,8,0)); val decoded=Json.decodeFromString(PortableBackup.serializer(),Json.encodeToString(PortableBackup.serializer(),original)); assertEquals(2,decoded.manifest.backupFormatVersion); assertEquals(10,decoded.manifest.roomVersion); assertEquals(7L,decoded.data.tasks.single().dueLessonId); assertEquals("Математика",decoded.data.subjects.single().name); assertEquals("Какво правихме",decoded.data.lessons.first().topic); assertEquals("Подготовка за матура", decoded.data.privateLessons.single().privateName); assertEquals("ONLINE", decoded.data.privateLessons.single().privateLocationKind) }
    @Test fun oldSlotWithoutLogicalBlockStillDecodesAsUngrouped() { val legacy = Json.decodeFromString(SlotDto.serializer(), "{\"id\":4,\"templateId\":2,\"weekday\":1,\"lessonIndex\":1,\"start\":\"08:00\",\"end\":\"08:45\",\"subjectId\":1,\"teacher\":null,\"room\":null,\"group\":null}"); assertEquals(null, legacy.logicalBlockId) }
    @Test fun independentPrivateFieldsRoundTripAndLegacyLessonDtoStillDecodes() { val independent = data.lessons.last().copy(subjectId = null, privateName = "Подготовка за матура", privateLocationKind = "ONLINE", teacher = "Иван Петров", room = "Google Meet"); val roundTrip = Json.decodeFromString(LessonDto.serializer(), Json.encodeToString(LessonDto.serializer(), independent)); assertEquals("Подготовка за матура", roundTrip.privateName); assertEquals("ONLINE", roundTrip.privateLocationKind); val legacy = Json.decodeFromString(LessonDto.serializer(), "{\"id\":7,\"date\":\"2026-09-20\",\"start\":\"16:00\",\"end\":\"17:00\",\"subjectId\":1,\"slotId\":null,\"privateId\":5,\"kind\":\"PRIVATE\",\"cancellation\":\"ACTIVE\",\"teacher\":null,\"room\":null,\"topic\":null,\"notes\":null}"); assertEquals(null, legacy.privateName); assertEquals(null, legacy.privateLocationKind) }
    @Test fun legacyRecurringDtoDecodesWithItsLabelForRestoreFallback() { val legacy = Json.decodeFromString(PrivateDto.serializer(), "{\"id\":5,\"subjectId\":1,\"weekday\":7,\"start\":\"16:00\",\"end\":\"17:00\",\"startDate\":\"2026-09-13\",\"endDate\":null,\"interval\":1,\"teacher\":\"Частен преподавател\",\"room\":\"При преподавателя\",\"label\":\"Математика\",\"enabled\":true}"); assertEquals("Математика", legacy.label); assertEquals(null, legacy.privateName); assertEquals(null, legacy.privateLocationKind) }
    @Test fun csvEscapesCommasQuotesNewlinesAndEmptyValues() { assertEquals("\"a, b\",\"\"\"quote\"\"\",\"line\nnext\",\"\"\n",CsvExport.row(listOf("a, b","\"quote\"","line\nnext",null))); assertTrue(CsvExport.row(listOf("Домашна работа")).contains("Домашна работа")) }
    @Test fun legacySettingsWithoutAcademicYearDatesUseDefaults() { val settings = Json.decodeFromString(BackupSettings.serializer(), "{\"taskRemindersEnabled\":false,\"dailySummaryEnabled\":false,\"summaryHour\":8,\"summaryMinute\":0}"); assertEquals(null, settings.schoolYearStart); assertEquals(SchoolYear.defaultStart, SchoolYear.fromStrings(settings.schoolYearStart, settings.schoolYearEnd).startDate) }
    @Test fun legacyTaskDtoWithoutIntendedDueUsesCurrentDueAsFallback() { val legacy = Json.decodeFromString(TaskDto.serializer(), "{\"id\":8,\"title\":\"Домашна\",\"description\":null,\"subjectId\":1,\"originId\":6,\"dueLessonId\":7,\"type\":\"HOMEWORK\",\"priority\":\"MUST\",\"status\":\"PENDING\",\"dueAt\":\"2026-09-20T16:00\",\"completedAt\":null,\"createdAt\":\"2026-09-14T09:00\"}"); assertEquals(7L, legacy.intendedDueLessonInstanceId) }
}
